create extension if not exists vector with schema extensions;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,preferences jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 200),description text,settings jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.project_members(project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','editor','viewer')),created_at timestamptz not null default now(),primary key(project_id,user_id));
create table if not exists public.chats(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,title text,model text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),chat_id uuid not null references public.chats(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('system','user','assistant','tool')),content text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.files(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null,storage_path text not null unique,mime_type text,size_bytes bigint check(size_bytes is null or size_bytes>=0),checksum text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.file_chunks(id uuid primary key default gen_random_uuid(),file_id uuid not null references public.files(id) on delete cascade,chunk_index integer not null check(chunk_index>=0),content text not null,embedding extensions.vector(1536),metadata jsonb not null default '{}',created_at timestamptz not null default now(),unique(file_id,chunk_index));
create table if not exists public.memories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,content text not null,memory_type text not null default 'semantic',source text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memory_embeddings(id uuid primary key default gen_random_uuid(),memory_id uuid not null unique references public.memories(id) on delete cascade,embedding extensions.vector(1536) not null,model text,created_at timestamptz not null default now());
create table if not exists public.mcp_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,name text not null,server_url text,transport text,secret_ref text,config jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.tools(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete cascade,name text not null,description text,source text,schema jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists public.tool_permissions(tool_id uuid not null references public.tools(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission text not null check(permission in('use','admin')),created_at timestamptz not null default now(),primary key(tool_id,user_id));
create table if not exists public.github_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_login text,installation_id bigint,access_token_ref text,scopes text[] not null default '{}',metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,account_login));
create table if not exists public.cowork_sessions(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,status text not null default 'active' check(status in('active','paused','completed','cancelled')),metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.cowork_members(session_id uuid not null references public.cowork_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','member','observer')),created_at timestamptz not null default now(),primary key(session_id,user_id));
create table if not exists public.permission_grants(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,resource_type text not null,resource_id uuid,action text not null,effect text not null default 'allow' check(effect in('allow','deny')),expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,project_id uuid references public.projects(id) on delete set null,action text not null,resource_type text,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
